const esc = (t) => String(t ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = (u) => /^https?:\/\/[^\s"'<>]+$/i.test(String(u || '')) ? esc(u) : '#';
const cveUrl = (id) => /^CVE-\d{4}-\d{4,}$/i.test(String(id || '')) ? 'https://nvd.nist.gov/vuln/detail/' + String(id).toUpperCase() : '#';
const cfg = $('Config').first().json;
const arts = $input.all().map(i => i.json).filter(a => a && a.link);
if (arts.length === 0) return [];
const byGroup = {}; for (const a of arts) (byGroup[a.product_group || 'General'] ||= []).push(a);
const groups = Object.entries(byGroup).sort((a, b) => (a[0] === 'General') - (b[0] === 'General') || b[1].length - a[1].length);
const clip = (t, n) => { t = String(t || '').replace(/\s+/g, ' ').trim(); return t.length <= n ? t : t.slice(0, n).replace(/\s\S*$/, '') + '…'; };
let html = `<div style="font-family:Segoe UI,Arial,sans-serif;font-size:14px;color:#1b1f1c;max-width:760px">
<h2 style="margin:0 0 4px">Threat intel digest – ${arts.length} relevant items (last 24 h)</h2>
<p style="color:#666;margin:0 0 12px">Grouped by product. Summaries by Claude where available; full list on the dashboard.</p>`;
const PER_GROUP = 6;
for (const [g, list] of groups) {
  html += `<h3 style="margin:18px 0 6px;font-size:15px;border-bottom:2px solid #0f5e4a;padding-bottom:3px">${esc(g)} <span style="color:#666;font-weight:400;font-size:13px">(${list.length})</span></h3>`;
  for (const a of list.slice(0, PER_GROUP)) {
    html += `<div style="padding:8px 0 10px;border-top:1px solid #eee">
    <div><a href="${safeUrl(a.link)}" style="font-weight:600">${esc(a.title)}</a> <span style="color:#666;font-size:12px">· ${esc(a.source)} · score ${Number(a.score) || 0}</span></div>
    ${a.ai_summary ? `<div style="margin-top:4px">${esc(a.ai_summary)}</div>${a.ai_reason ? `<div style="margin-top:3px;color:#0f5e4a;font-weight:600">→ ${esc(a.ai_reason)}</div>` : ''}` : `<div style="margin-top:4px;color:#444">${esc(clip(a.summary, 220))}</div>`}
    </div>`;
  }
  if (list.length > PER_GROUP) html += `<div style="color:#666;font-size:12px">…${list.length - PER_GROUP} more on the dashboard</div>`;
}
html += `<p style="margin-top:16px"><a href="${safeUrl(cfg.DASHBOARD_URL)}">Open dashboard</a></p></div>`;
const subject = `[Threat Intel] Daily digest – ${arts.length} items · ${groups.slice(0, 3).map(g => g[0]).join(', ')}`;
return [{ json: { html, subject, count: arts.length, links: arts.map(a => a.link) } }];
